import itertools
langs = ['Coq', 'V', 'Verilog']  # alphabetical = tie order
uniq = {'Coq': ['Theorem', 'Lemma', 'Require'], 'V': ['mut', 'pub', 'defer'], 'Verilog': ['always', 'wire', 'assign']}
def predict(membership, extras):
    # extras: dict lang -> number of unique keywords added
    scores = {l: extras.get(l, 0) + (1 if l in membership else 0) for l in langs}
    best = max(scores.values())
    return sorted([l for l in langs if scores[l] == best])[0]
combos = []
for r in range(0, 4):
    for c in itertools.combinations(langs, r):
        combos.append(frozenset(c))
# candidate tests: extras vectors with 0..2 per language
tests = [dict(zip(langs, v)) for v in itertools.product(range(3), repeat=3)]
# find minimal set of tests distinguishing all combos
best = None
for k in range(1, 5):
    for tset in itertools.combinations(tests, k):
        sigs = {}
        ok = True
        for c in combos:
            sig = tuple(predict(c, t) for t in tset)
            if sig in sigs: ok = False; break
            sigs[sig] = c
        if ok:
            best = tset; break
    if best: break
print(best)
EOF"}

