import json
d1 = json.load(open('complexity_probe.json'))
d2 = json.load(open('complexity_probe2.json'))
variants_order = [' ', '(x)', '{', '', ':', '[', '.', '\t']
def derive(det):
    toks = []
    for w, vs in det.items():
        vset = {v for v, n in vs}
        if '' in vset:
            toks.append(w); continue
        if ' ' in vset or ' x' in vset: toks.append(w + ' ')
        if '(x)' in vset: toks.append(w + '(')
        if '{' in vset: toks.append(w + '{')
        if ':' in vset: toks.append(w + ':')
        if '[' in vset: toks.append(w + '[')
        if '.' in vset: toks.append(w + '.')
        if '\t' in vset: toks.append(w + '\t')
    return toks
out = {}
for lang in d1:
    toks = set(derive(d1[lang])) | set(derive(d2.get(lang, {})))
    # reduce: remove tokens having a proper prefix that is a bare token (no trailing special) in set
    bare = {t for t in toks if not t.endswith((' ', '(', '{', ':', '[', '.', '\t'))}
    red = []
    for t in sorted(toks):
        if any(b != t and t.startswith(b) for b in bare): continue
        red.append(t)
    # also: if 'w ' and 'w(' etc exist along with bare 'w' -> handled above
    out[lang] = red
json.dump(out, open('complexity_final.json', 'w'), indent=1)
