import itertools
def simulate(content, quotes, P):
    # returns state at first '\n' or at end
    qs = quotes if P['order'] == 'long' else list(reversed(quotes))
    i = 0; state = 'code'; end = None; ign = False; n = len(content)
    while i < n:
        c = content[i]
        if c == '\n': return state
        if state == 'code':
            for s, e, ig in qs:
                L = len(s)
                ok = content.startswith(s, i) and (i + L <= n if P['obound'] == 'le' else i + L < n)
                if ok:
                    state = 'string'; end = e; ign = ig
                    i = {'i': i, 'i+L-1': i + L - 1, 'i+L': i + L}[P['oret']]
                    if ig and P['ignskip']: i += 1
                    break
        elif state == 'string':
            L = len(end)
            if P['cdir'] == 'fwd':
                m = content.startswith(end, i) and (i + L <= n if P['cbound'] == 'le' else i + L < n)
            else:
                m = i - L + 1 >= 0 and content[i-L+1:i+1] == end
            if m and (ign or content[i-1] != '\\'):
                state = 'code'
                i = {'j': i, 'j+L-1': i + L - 1, 'j+L': i + L}[P['cret']]
        i += 1
    return state
