obs_a = {1:'open',2:'open',3:'closed',4:'open',5:'open',6:'open',7:'open',8:'closed',9:'open',10:'open',11:'open',12:'open',13:'closed',14:'open'}
obs_b = {1:'open',2:'closed',3:'open',4:'open',5:'open',6:'open',7:'closed',8:'open',9:'open',10:'open',11:'open',12:'closed',13:'open',14:'open'}
go_tests = [('x = ``\n', 'open'), ('x = `a`\n', 'closed'), ('x = ```\n', 'closed'), ('x = ````\n', 'open'), ('x = `````\n', 'open'), ('x = ` `\n', 'closed'), ('x = ""\n', 'closed'), ('x = """\n', 'open'), ('x = """"\n', 'closed'), ('x = """""\n', 'open'), ('x = "\\"\n', 'open'), ('x = "a\\"\n', 'open'), ('x = "a\\\\"\n', 'closed')]
keys = ['order', 'obound', 'oret', 'ignskip', 'cdir', 'cbound', 'cret']
space = {'order': ['long', 'short'], 'obound': ['le', 'lt'], 'oret': ['i', 'i+L-1', 'i+L'], 'ignskip': [False, True], 'cdir': ['fwd', 'bwd'], 'cbound': ['le', 'lt'], 'cret': ['j', 'j+L-1', 'j+L']}
