package main

import (
	"bytes"
	_ "embed"
	"encoding/json"
	"path/filepath"
	"sort"
	"strings"
)

//go:embed languages.json
var languagesJSON []byte

// Quote describes a string literal delimiter pair.
type Quote struct {
	Start        string `json:"start"`
	End          string `json:"end"`
	DocString    bool   `json:"docstring"`
	IgnoreEscape bool   `json:"ignoreEscape"`
}

// LanguageDef is the static definition of a language loaded from languages.json.
type LanguageDef struct {
	Name           string     `json:"name"`
	Extensions     []string   `json:"extensions"`
	Filenames      []string   `json:"filenames"`
	ListExtensions []string   `json:"listExtensions"`
	LineComment    []string   `json:"lineComment"`
	MultiLine      [][]string `json:"multiLine"`
	Quotes         []Quote    `json:"quotes"`
	NestedComments bool       `json:"nestedComments"`
	Complexity     []string   `json:"complexity"`
	Shebangs       []string   `json:"shebangs"`
	Keywords       []string   `json:"keywords"`
	KeywordBase    int        `json:"keywordBase"`
}

// LanguageFeature holds the byte-level lookup structures used by the counter.
type LanguageFeature struct {
	Name            string
	LineComment     [][]byte
	MultiOpen       [][]byte
	MultiClose      [][]byte
	QuoteStart      [][]byte
	QuoteEnd        [][]byte
	QuoteDoc        []bool
	QuoteIgnoreEsc  []bool
	Nested          bool
	Complexity      [][]byte
	Keywords        []string
	KeywordBase     int
	HasComplexity   bool
	HasLineComment  bool
	HasMultiComment bool
	HasQuotes       bool
}

var (
	LanguageDefs        []LanguageDef
	LanguageByName      = map[string]*LanguageDef{}
	LanguageFeatures    = map[string]*LanguageFeature{}
	ExtensionToLanguage = map[string][]string{}
	FilenameToLanguage  = map[string]string{}
	ShebangToLanguage   = map[string]string{}
)

func loadLanguages() {
	if err := json.Unmarshal(languagesJSON, &LanguageDefs); err != nil {
		panic(err)
	}
	for i := range LanguageDefs {
		d := &LanguageDefs[i]
		LanguageByName[d.Name] = d
		for _, e := range d.Extensions {
			ExtensionToLanguage[e] = append(ExtensionToLanguage[e], d.Name)
		}
		for _, f := range d.Filenames {
			FilenameToLanguage[f] = d.Name
		}
		for _, s := range d.Shebangs {
			ShebangToLanguage[s] = d.Name
		}
		LanguageFeatures[d.Name] = buildFeature(d)
	}
}

func buildFeature(d *LanguageDef) *LanguageFeature {
	f := &LanguageFeature{Name: d.Name, Nested: d.NestedComments, Keywords: d.Keywords, KeywordBase: d.KeywordBase}
	for _, c := range d.LineComment {
		f.LineComment = append(f.LineComment, []byte(c))
	}
	for _, m := range d.MultiLine {
		f.MultiOpen = append(f.MultiOpen, []byte(m[0]))
		f.MultiClose = append(f.MultiClose, []byte(m[1]))
	}
	for _, q := range d.Quotes {
		f.QuoteStart = append(f.QuoteStart, []byte(q.Start))
		f.QuoteEnd = append(f.QuoteEnd, []byte(q.End))
		f.QuoteDoc = append(f.QuoteDoc, q.DocString)
		f.QuoteIgnoreEsc = append(f.QuoteIgnoreEsc, q.IgnoreEscape)
	}
	for _, c := range d.Complexity {
		f.Complexity = append(f.Complexity, []byte(c))
	}
	f.HasComplexity = len(f.Complexity) > 0
	f.HasLineComment = len(f.LineComment) > 0
	f.HasMultiComment = len(f.MultiOpen) > 0
	f.HasQuotes = len(f.QuoteStart) > 0
	return f
}

// languageExists reports whether a language with the given name exists (case-insensitive).
func canonicalLanguageName(name string) (string, bool) {
	if _, ok := LanguageByName[name]; ok {
		return name, true
	}
	lower := strings.ToLower(name)
	for _, d := range LanguageDefs {
		if strings.ToLower(d.Name) == lower {
