		}
	}
	return "", false
}

// getExtension works out the extension for a filename following the original
// tool's rules: the last two dot separated parts are tried first.
func getExtension(name string) string {
	name = strings.ToLower(name)
	ext := filepath.Ext(name)
	if ext == "" || strings.LastIndex(name, ".") == 0 {
		return name
	}
	sub := filepath.Ext(strings.TrimSuffix(name, ext))
	return strings.TrimPrefix(sub+ext, ".")
}

// hasRealExtension reports whether a filename has something that counts as an extension.
func hasRealExtension(name string) bool {
	lower := strings.ToLower(name)
	ext := filepath.Ext(lower)
	if ext == "" || strings.LastIndex(lower, ".") == 0 {
		return false
	}
	return true
}

// detectByExtension detects languages using only the extension map.
func detectByExtension(name string) ([]string, string) {
	lower := strings.ToLower(name)
	if !hasRealExtension(name) {
		return nil, ""
	}
	if langs, ok := ExtensionToLanguage[lower]; ok {
		return langs, ""
	}
	ext := getExtension(name)
	if langs, ok := ExtensionToLanguage[ext]; ok {
		return langs, ext
	}
