	if strings.LastIndex(ext, ".") > 0 {
		short := ext[strings.LastIndex(ext, ".")+1:]
		if langs, ok := ExtensionToLanguage[short]; ok {
			return langs, short
		}
		return nil, ext
	}
	return nil, ext
}

// DetectLanguage returns the possible languages for a filename and the extension used.
func DetectLanguage(name string) ([]string, string) {
	lower := strings.ToLower(name)
	if lang, ok := FilenameToLanguage[lower]; ok {
		return []string{lang}, name
	}
	return detectByExtension(name)
}

// DetectSheBang tries to determine the language from a #! line.
func DetectSheBang(content []byte) (string, bool) {
	if !bytes.HasPrefix(content, []byte("#!")) {
		return "", false
	}
	line := content[2:]
	if idx := bytes.IndexByte(line, '\n'); idx >= 0 {
		line = line[:idx]
	}
	fields := strings.Fields(string(line))
	if len(fields) == 0 {
		return "", false
	}
	cmd := fields[0]
	idx := strings.LastIndex(cmd, "/")
	if idx < 0 {
		return "", false
	}
	base := cmd[idx+1:]
	if base == "env" {
		if len(fields) < 2 {
			return "", false
		}
		base = fields[1]
	}
	if lang, ok := ShebangToLanguage[base]; ok {
		return lang, true
	}
	return "", false
}

type languageGuess struct {
	Name  string
	Count int
}

// DetermineLanguage picks between several possible languages by looking for keywords.
func DetermineLanguage(fallback string, possible []string, content []byte) string {
	if len(possible) == 0 {
		return fallback
	}
	if len(possible) == 1 {
		return possible[0]
	}
	toCheck := content
	if len(toCheck) > 20000 {
		toCheck = toCheck[:20000]
	}
	primary := ""
	guesses := make([]languageGuess, 0, len(possible))
	for _, lan := range possible {
		f := LanguageFeatures[lan]
		if f == nil {
			continue
		}
		if len(f.Keywords) == 0 {
			primary = lan
		}
		count := f.KeywordBase
		for _, k := range f.Keywords {
			if bytes.Contains(toCheck, []byte(k)) {
				count++
			}
		}
		guesses = append(guesses, languageGuess{Name: lan, Count: count})
	}
	sort.Slice(guesses, func(i, j int) bool {
		if guesses[i].Count == guesses[j].Count {
			return guesses[i].Name < guesses[j].Name
		}
		return guesses[i].Count > guesses[j].Count
	})
	if len(guesses) == 0 {
		return fallback
	}
	if primary != "" {
		allBase := true
		for _, g := range guesses {
			f := LanguageFeatures[g.Name]
			if g.Count != f.KeywordBase {
				allBase = false
			}
		}
		if allBase {
			return primary
		}
	}
	return guesses[0].Name
}
