cd /workspace && cat > process.go <<'EOF'
package main

import (
	"bytes"
	"crypto/md5"
	"encoding/hex"
	"strings"
)

const (
	sBlank             = 1
	sCode              = 2
	sComment           = 3
	sCommentCode       = 4
	sMultiComment      = 5
	sMultiCommentCode  = 6
	sMultiCommentBlank = 7
	sString            = 8
	sDocString         = 9
)

// FileJob represents a single file being counted.
type FileJob struct {
	Language           string
	PossibleLanguages  []string
	Filename           string
	Extension          string
	Location           string
	Symlocation        string
	Content            []byte
	Bytes              int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	WeightedComplexity float64
	Hash               []byte
	Binary             bool
	Minified           bool
	Generated          bool
	EndPoint           int
	Uloc               int
	LineLength         []int
	UniqueLines        map[string]struct{}
}

func isWhitespace(b byte) bool {
	return b == ' ' || b == '\t' || b == '\n' || b == '\r'
}

func hasPrefixAt(content []byte, index int, token []byte) bool {
	if index+len(token) > len(content) {
		return false
	}
	for i, b := range token {
		if content[index+i] != b {
			return false
		}
	}
	return true
}

type counter struct {
	job        *FileJob
	feat       *LanguageFeature
	content    []byte
	n          int
	state      int
	endString  []byte
	ignoreEsc  bool
	closers    [][]byte // stack of multi-line comment closers
	complexity bool
}

func (c *counter) matchMultiOpen(i int) int {
	for k, open := range c.feat.MultiOpen {
		if hasPrefixAt(c.content, i, open) {
			return k
		}
	}
	return -1
}

func (c *counter) matchLineComment(i int) int {
	for k, tok := range c.feat.LineComment {
		if hasPrefixAt(c.content, i, tok) {
			return k
		}
	}
	return -1
}

func (c *counter) matchQuote(i int) int {
	for k, tok := range c.feat.QuoteStart {
		if hasPrefixAt(c.content, i, tok) {
			return k
		}
	}
	return -1
}

func (c *counter) checkComplexity(i int) (int, bool) {
	if !c.complexity || !c.feat.HasComplexity {
		return i, false
	}
	if i != 0 && !isWhitespace(c.content[i-1]) {
		return i, false
	}
	for _, tok := range c.feat.Complexity {
		if hasPrefixAt(c.content, i, tok) {
			c.job.Complexity++
			return i + len(tok) - 1, true
		}
	}
	return i, false
}

func (c *counter) blankState(i int) int {
	if ni, ok := c.checkComplexity(i); ok {
		c.state = sCode
		return ni
	}
	if k := c.matchMultiOpen(i); k >= 0 {
		c.closers = append(c.closers[:0], c.feat.MultiClose[k])
		c.state = sMultiComment
		return i + len(c.feat.MultiOpen[k]) - 1
	}
	if k := c.matchLineComment(i); k >= 0 {
		c.state = sComment
		return i + len(c.feat.LineComment[k]) - 1
	}
	if k := c.matchQuote(i); k >= 0 {
		c.endString = c.feat.QuoteEnd[k]
		c.ignoreEsc = c.feat.QuoteIgnoreEsc[k]
		if c.feat.QuoteDoc[k] {
			c.state = sDocString
		} else {
			c.state = sString
		}
		if c.ignoreEsc {
			return i + len(c.feat.QuoteStart[k])
		}
		return i
	}
	c.state = sCode
	return i
}

func (c *counter) codeState(i int) int {
	if c.content[i] == 0 && i < 10000 {
		c.job.Binary = true
		return i
	}
	if ni, ok := c.checkComplexity(i); ok {
		return ni
	}
	if k := c.matchMultiOpen(i); k >= 0 {
		c.closers = append(c.closers[:0], c.feat.MultiClose[k])
		c.state = sMultiCommentCode
		return i + len(c.feat.MultiOpen[k]) - 1
	}
	if k := c.matchLineComment(i); k >= 0 {
		c.state = sCommentCode
		return i + len(c.feat.LineComment[k]) - 1
	}
	if k := c.matchQuote(i); k >= 0 {
		c.endString = c.feat.QuoteEnd[k]
		c.ignoreEsc = c.feat.QuoteIgnoreEsc[k]
		c.state = sString
		if c.ignoreEsc {
			return i + len(c.feat.QuoteStart[k])
		}
		return i
	}
	return i
}

func (c *counter) commentState(i int) int {
	if c.feat.Nested {
		if k := c.matchMultiOpen(i); k >= 0 {
			c.closers = append(c.closers, c.feat.MultiClose[k])
			return i + len(c.feat.MultiOpen[k]) - 1
		}
	}
	if len(c.closers) > 0 {
		cl := c.closers[len(c.closers)-1]
		if hasPrefixAt(c.content, i, cl) {
			c.closers = c.closers[:len(c.closers)-1]
			if len(c.closers) == 0 {
				if c.state == sMultiCommentCode {
					c.state = sCode
				} else {
					c.state = sMultiCommentBlank
				}
			}
			return i + len(cl) - 1
		}
	}
	return i
}

func (c *counter) stringState(i int) int {
	for k := i; k < c.n; k++ {
		b := c.content[k]
		if b == '\n' {
			return k
		}
		if !c.ignoreEsc && b == '\\' {
			if k+1 < c.n && c.content[k+1] != '\n' {
				k++
			}
			continue
		}
		if hasPrefixAt(c.content, k, c.endString) {
			c.state = sCode
			return k
		}
	}
	return c.n - 1
}

func (c *counter) docStringState(i int) int {
	for k := i; k < c.n; k++ {
		b := c.content[k]
		if b == '\n' {
			return k
		}
		if !c.ignoreEsc && b == '\\' {
			if k+1 < c.n && c.content[k+1] != '\n' {
				k++
			}
			continue
		}
		if hasPrefixAt(c.content, k, c.endString) {
			j := k + len(c.endString)
			if j >= c.n {
				return k
			}
			for ; j < c.n; j++ {
				if c.content[j] == '\n' {
					c.state = sComment
					return k
				}
				if !isWhitespace(c.content[j]) {
					c.state = sCode
					return k
				}
			}
			c.state = sCode
			return k
		}
	}
	return c.n - 1
}

func resetState(state int) int {
	switch state {
	case sMultiComment, sMultiCommentCode:
		return sMultiComment
	case sString:
		return sString
	case sDocString:
		return sDocString
	}
	return sBlank
}

// CountStats runs the line counting state machine over the file content.
func CountStats(job *FileJob, feat *LanguageFeature, complexity bool) {
	content := job.Content
	n := len(content)
	job.Bytes = int64(n)
	if n == 0 {
		return
	}
	c := &counter{job: job, feat: feat, content: content, n: n, state: sBlank, complexity: complexity}
	for i := 0; i < n; i++ {
		b := content[i]
		if !isWhitespace(b) {
			switch c.state {
			case sBlank, sMultiCommentBlank:
				i = c.blankState(i)
			case sCode:
				i = c.codeState(i)
			case sString:
				i = c.stringState(i)
			case sDocString:
				i = c.docStringState(i)
			case sMultiComment, sMultiCommentCode:
				i = c.commentState(i)
			}
		}
		if i >= n {
			return
		}
		if job.Binary {
			return
		}
		if content[i] == '\n' || i == n-1 {
			job.Lines++
			switch c.state {
			case sBlank:
				job.Blank++
			case sCode, sString, sCommentCode, sMultiCommentCode:
				job.Code++
			case sComment, sMultiComment, sMultiCommentBlank, sDocString:
				job.Comment++
			}
			c.state = resetState(c.state)
		}
	}
}

// computeLineLengths fills in the per line byte lengths used by the --character option.
func computeLineLengths(job *FileJob) {
	content := bytes.TrimRight(job.Content, "\n")
	if len(job.Content) == 0 {
		job.LineLength = nil
		return
	}
	parts := bytes.Split(content, []byte{'\n'})
	job.LineLength = make([]int, 0, len(parts))
	for _, p := range parts {
		job.LineLength = append(job.LineLength, len(p))
	}
}

// computeUniqueLines fills in the set of unique lines for ULOC.
func computeUniqueLines(job *FileJob) {
	job.UniqueLines = map[string]struct{}{}
	if len(job.Content) == 0 {
		return
	}
	content := strings.TrimRight(string(job.Content), "\n")
	for _, l := range strings.Split(content, "\n") {
		job.UniqueLines[l] = struct{}{}
	}
	job.Uloc = len(job.UniqueLines)
}

func computeHash(job *FileJob) {
	h := md5.Sum(job.Content)
	job.Hash = h[:]
}

func hashString(b []byte) string {
	return hex.EncodeToString(b)
}

// checkGenerated inspects the start of the file for generator markers.
func checkGenerated(job *FileJob, markers []string) {
	head := job.Content
	if len(head) > 1000 {
		head = head[:1000]
	}
	lower := bytes.ToLower(head)
	for _, m := range markers {
		if bytes.Contains(lower, []byte(strings.ToLower(m))) {
			job.Generated = true
			return
		}
	}
}

// checkMinified checks whether the average line length exceeds the limit.
func checkMinified(job *FileJob, limit int64) {
	if job.Lines == 0 {
		return
	}
	if job.Bytes/job.Lines >= limit {
		job.Minified = true
	}
}
EOF
echo ok

