cat > flags.go <<'EOF'
package main

import (
	"fmt"
	"strconv"
	"strings"
)

type flagKind int

const (
	kindBool flagKind = iota
	kindString
	kindInt
	kindFloat
	kindStrings     // comma separated list, may be repeated
	kindStringArray // repeated, not split
)

type flagDef struct {
	long      string
	short     string
	kind      flagKind
	usage     string
	defString string
	// targets
	boolVal   *bool
	strVal    *string
	intVal    *int64
	floatVal  *float64
	sliceVal  *[]string
	changed   bool
	typeLabel string
}

type flagSet struct {
	defs   []*flagDef
	byLong map[string]*flagDef
	byShrt map[string]*flagDef
	args   []string
}

func newFlagSet() *flagSet {
	return &flagSet{byLong: map[string]*flagDef{}, byShrt: map[string]*flagDef{}}
}

func (fs *flagSet) add(d *flagDef) {
	fs.defs = append(fs.defs, d)
	fs.byLong[d.long] = d
	if d.short != "" {
		fs.byShrt[d.short] = d
	}
}

func (fs *flagSet) Bool(p *bool, long, short string, def bool, usage string) {
	*p = def
	fs.add(&flagDef{long: long, short: short, kind: kindBool, usage: usage, boolVal: p, typeLabel: ""})
}

func (fs *flagSet) String(p *string, long, short string, def string, usage string) {
	*p = def
	fs.add(&flagDef{long: long, short: short, kind: kindString, usage: usage, strVal: p, defString: def, typeLabel: "string"})
}

func (fs *flagSet) Int(p *int64, long, short string, def int64, usage string) {
	*p = def
	fs.add(&flagDef{long: long, short: short, kind: kindInt, usage: usage, intVal: p, defString: strconv.FormatInt(def, 10), typeLabel: "int"})
}

func (fs *flagSet) Float(p *float64, long, short string, def float64, usage string) {
	*p = def
	fs.add(&flagDef{long: long, short: short, kind: kindFloat, usage: usage, floatVal: p, defString: strconv.FormatFloat(def, 'g', -1, 64), typeLabel: "float"})
}

func (fs *flagSet) Strings(p *[]string, long, short string, def []string, usage string) {
	*p = append([]string{}, def...)
	fs.add(&flagDef{long: long, short: short, kind: kindStrings, usage: usage, sliceVal: p, defString: "[" + strings.Join(def, ",") + "]", typeLabel: "strings"})
}

func (fs *flagSet) StringArray(p *[]string, long, short string, def []string, usage string) {
	*p = append([]string{}, def...)
	fs.add(&flagDef{long: long, short: short, kind: kindStringArray, usage: usage, sliceVal: p, defString: "[" + strings.Join(def, ",") + "]", typeLabel: "stringArray"})
}

func splitCSV(v string) []string {
	if v == "" {
		return []string{}
	}
	parts := strings.Split(v, ",")
	return parts
}

func (d *flagDef) set(value string, flagName string) error {
	switch d.kind {
	case kindBool:
		b, err := strconv.ParseBool(value)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
		}
		*d.boolVal = b
	case kindString:
		*d.strVal = value
	case kindInt:
		i, err := strconv.ParseInt(value, 0, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
		}
		*d.intVal = i
	case kindFloat:
		f, err := strconv.ParseFloat(value, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
		}
		*d.floatVal = f
	case kindStrings:
		if !d.changed {
			*d.sliceVal = splitCSV(value)
		} else {
			*d.sliceVal = append(*d.sliceVal, splitCSV(value)...)
		}
	case kindStringArray:
		if !d.changed {
			*d.sliceVal = []string{value}
		} else {
			*d.sliceVal = append(*d.sliceVal, value)
		}
	}
	d.changed = true
	return nil
}

// Parse parses the arguments in a pflag compatible manner.
func (fs *flagSet) Parse(args []string) error {
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			fs.args = append(fs.args, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			d, ok := fs.byLong[name]
			if !ok {
				return fmt.Errorf("unknown flag: --%s", name)
			}
			if d.kind == kindBool {
				if !hasValue {
					value = "true"
				}
			} else if !hasValue {
				if i+1 >= len(args) {
					return fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				value = args[i]
			}
			if err := d.set(value, "--"+name); err != nil {
				return err
			}
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			shorts := a[1:]
			for j := 0; j < len(shorts); j++ {
				ch := string(shorts[j])
				d, ok := fs.byShrt[ch]
				if !ok {
					return fmt.Errorf("unknown shorthand flag: '%s' in -%s", ch, shorts)
				}
				if d.kind == kindBool {
					value := "true"
					if j+1 < len(shorts) && shorts[j+1] == '=' {
						value = shorts[j+2:]
						if err := d.set(value, "-"+ch); err != nil {
							return err
						}
						break
					}
					if err := d.set(value, "-"+ch); err != nil {
						return err
					}
					continue
				}
				var value string
				if j+1 < len(shorts) {
					value = shorts[j+1:]
					if strings.HasPrefix(value, "=") {
						value = value[1:]
					}
				} else {
					if i+1 >= len(args) {
						return fmt.Errorf("flag needs an argument: '%s' in -%s", ch, shorts)
					}
					i++
					value = args[i]
				}
				if err := d.set(value, "-"+ch); err != nil {
					return err
				}
				break
			}
			continue
		}
		fs.args = append(fs.args, a)
	}
	return nil
}

// Usage renders the flag usage block the same way cobra/pflag would.
func (fs *flagSet) Usage() string {
	type line struct {
		left  string
		right string
	}
	lines := []line{}
	maxLen := 0
	for _, d := range fs.defs {
		var left string
		if d.short != "" {
			left = fmt.Sprintf("  -%s, --%s", d.short, d.long)
		} else {
			left = fmt.Sprintf("      --%s", d.long)
		}
		if d.typeLabel != "" {
			left += " " + d.typeLabel
		}
		right := d.usage
		switch d.kind {
		case kindString:
			if d.defString != "" {
				right += fmt.Sprintf(" (default %q)", d.defString)
			}
		case kindInt:
			if d.defString != "0" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		case kindFloat:
			if d.defString != "0" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		case kindStrings, kindStringArray:
			if d.defString != "[]" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		}
		if len(left) > maxLen {
			maxLen = len(left)
		}
		lines = append(lines, line{left, right})
	}
	var sb strings.Builder
	for _, l := range lines {
		sb.WriteString(l.left)
		sb.WriteString(strings.Repeat(" ", maxLen-len(l.left)+3))
		sb.WriteString(l.right)
		sb.WriteString("\n")
	}
	return sb.String()
}
EOF
echo ok"}

