			return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
		}
		*d.intVal = i
	case kindFloat:
		f, err := strconv.ParseFloat(value, 64)
		if err != nil {
			return fmt.Errorf("invalid argument %q for %q flag: %v", value, flagName, err)
		}
		*d.floatVal = f
	case kindStrings:
		if !d.changed {
			*d.sliceVal = splitCSV(value)
		} else {
			*d.sliceVal = append(*d.sliceVal, splitCSV(value)...)
		}
	case kindStringArray:
		if !d.changed {
			*d.sliceVal = []string{value}
		} else {
			*d.sliceVal = append(*d.sliceVal, value)
		}
	}
	d.changed = true
	return nil
}

// Parse parses the arguments in a pflag compatible manner.
func (fs *flagSet) Parse(args []string) error {
	for i := 0; i < len(args); i++ {
		a := args[i]
		if a == "--" {
			fs.args = append(fs.args, args[i+1:]...)
			break
		}
		if strings.HasPrefix(a, "--") {
			name := a[2:]
			value := ""
			hasValue := false
			if idx := strings.Index(name, "="); idx >= 0 {
				value = name[idx+1:]
				name = name[:idx]
				hasValue = true
			}
			d, ok := fs.byLong[name]
			if !ok {
				return fmt.Errorf("unknown flag: --%s", name)
			}
			if d.kind == kindBool {
				if !hasValue {
					value = "true"
				}
			} else if !hasValue {
				if i+1 >= len(args) {
					return fmt.Errorf("flag needs an argument: --%s", name)
				}
				i++
				value = args[i]
			}
			if err := d.set(value, "--"+name); err != nil {
				return err
			}
			continue
		}
		if strings.HasPrefix(a, "-") && len(a) > 1 {
			shorts := a[1:]
			for j := 0; j < len(shorts); j++ {
				ch := string(shorts[j])
				d, ok := fs.byShrt[ch]
				if !ok {
					return fmt.Errorf("unknown shorthand flag: '%s' in -%s", ch, shorts)
				}
				if d.kind == kindBool {
					value := "true"
					if j+1 < len(shorts) && shorts[j+1] == '=' {
						value = shorts[j+2:]
						if err := d.set(value, "-"+ch); err != nil {
							return err
						}
						break
					}
					if err := d.set(value, "-"+ch); err != nil {
						return err
					}
					continue
				}
				var value string
				if j+1 < len(shorts) {
					value = shorts[j+1:]
					if strings.HasPrefix(value, "=") {
						value = value[1:]
					}
				} else {
					if i+1 >= len(args) {
						return fmt.Errorf("flag needs an argument: '%s' in -%s", ch, shorts)
					}
					i++
					value = args[i]
				}
				if err := d.set(value, "-"+ch); err != nil {
					return err
				}
				break
			}
			continue
		}
		fs.args = append(fs.args, a)
	}
	return nil
}

// Usage renders the flag usage block the same way cobra/pflag would.
func (fs *flagSet) Usage() string {
	type line struct {
		left  string
		right string
	}
	lines := []line{}
	maxLen := 0
	for _, d := range fs.defs {
		var left string
		if d.short != "" {
			left = fmt.Sprintf("  -%s, --%s", d.short, d.long)
		} else {
			left = fmt.Sprintf("      --%s", d.long)
		}
		if d.typeLabel != "" {
			left += " " + d.typeLabel
		}
		right := d.usage
		switch d.kind {
		case kindString:
			if d.defString != "" {
				right += fmt.Sprintf(" (default %q)", d.defString)
			}
		case kindInt:
			if d.defString != "0" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		case kindFloat:
			if d.defString != "0" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		case kindStrings, kindStringArray:
			if d.defString != "[]" {
				right += fmt.Sprintf(" (default %s)", d.defString)
			}
		}
		if len(left) > maxLen {
			maxLen = len(left)
		}
		lines = append(lines, line{left, right})
	}
	var sb strings.Builder
	for _, l := range lines {
		sb.WriteString(l.left)
		sb.WriteString(strings.Repeat(" ", maxLen-len(l.left)+3))
		sb.WriteString(l.right)
		sb.WriteString("\n")
	}
	return sb.String()
}
