			continue
		}
		if strings.HasPrefix(line, "/") {
			p.anchored = true
			line = strings.TrimLeft(line, "/")
		} else if strings.Contains(line, "/") {
			p.anchored = true
		}
		if strings.HasPrefix(line, "**/") {
			// matches in any directory
			p.anchored = false
			line = strings.TrimPrefix(line, "**/")
