		}
		p.re = re
		m.patterns = append(m.patterns, p)
	}
}

// matches reports whether relPath (relative to the walk root, forward slashes) is ignored.
func (m *ignoreMatcher) matches(relPath string, isDir bool) bool {
	if len(m.patterns) == 0 {
		return false
	}
	ignored := false
	matchedAny := false
	for _, p := range m.patterns {
		// path relative to pattern base
		rel := relPath
		if p.base != "" {
			if !strings.HasPrefix(relPath, p.base+"/") {
				continue
			}
			rel = relPath[len(p.base)+1:]
		}
		if p.dirOnly && !isDir {
			continue
		}
		var ok bool
		if p.anchored {
			ok = p.re.MatchString(rel)
		} else {
			// match against basename or any trailing component sequence
			ok = p.re.MatchString(rel)
			if !ok {
				idx := strings.LastIndex(rel, "/")
				if idx >= 0 {
					ok = p.re.MatchString(rel[idx+1:])
				}
			}
		}
		if ok {
			matchedAny = true
			ignored = !p.negate
		}
	}
	_ = matchedAny
	return ignored
}

// clone makes a copy so sub directories can add rules without affecting siblings.
func (m *ignoreMatcher) clone() *ignoreMatcher {
	c := &ignoreMatcher{}
	c.patterns = append(c.patterns, m.patterns...)
	return c
