package main

import (
	"fmt"
	"os"
	"path/filepath"
	"regexp"
	"sort"
	"strings"
)

type walkConfig struct {
	excludeDirs   []string
	excludeFiles  []string
	notMatch      []*regexp.Regexp
	useGitignore  bool
	useIgnore     bool
	useSccIgnore  bool
	useGitmodules bool
	countIgnore   bool
	includeSyms   bool
}

type foundFile struct {
	location string // path as shown in output
	filename string // base name (or the argument for direct files)
	direct   bool
	symloc   string
}

func newWalkConfig() *walkConfig {
	cfg := &walkConfig{
		excludeDirs:   opts.ExcludeDir,
		excludeFiles:  opts.ExcludeFile,
		useGitignore:  !opts.NoGitignore,
		useIgnore:     !opts.NoIgnore,
		useSccIgnore:  !opts.NoSccIgnore,
		useGitmodules: !opts.NoGitmodule,
		countIgnore:   opts.CountIgnore,
		includeSyms:   opts.IncludeSymlinks,
	}
	for _, m := range opts.NotMatch {
		re, err := regexp.Compile(m)
		if err != nil {
			printError(fmt.Sprintf("failed to compile regular expression %s: %s", m, err.Error()))
			continue
		}
		cfg.notMatch = append(cfg.notMatch, re)
	}
	return cfg
}

func (cfg *walkConfig) dirExcluded(path, base string) bool {
	for _, ed := range cfg.excludeDirs {
		pat := strings.TrimRight(ed, "/")
		if pat == "" {
			continue
		}
		if base == pat || path == pat || strings.HasSuffix(path, "/"+pat) {
			return true
		}
	}
	for _, re := range cfg.notMatch {
		if re.MatchString(path) || re.MatchString(base) {
			return true
		}
	}
	return false
}

func (cfg *walkConfig) fileExcluded(path, base string) bool {
	for _, ef := range cfg.excludeFiles {
		if ef != "" && strings.Contains(base, ef) {
			return true
		}
	}
	for _, re := range cfg.notMatch {
		if re.MatchString(path) || re.MatchString(base) {
			return true
		}
	}
	return false
}

func readGitmodules(dir string) []string {
	content, err := os.ReadFile(filepath.Join(dir, ".gitmodules"))
	if err != nil {
		return nil
	}
	var paths []string
	for _, line := range strings.Split(string(content), "\n") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "path") {
			idx := strings.Index(line, "=")
			if idx >= 0 {
				p := strings.TrimSpace(line[idx+1:])
				if p != "" {
					paths = append(paths, p)
				}
			}
		}
	}
	return paths
}

// walk collects the files under the given roots.
func walk(roots []string, cfg *walkConfig) ([]foundFile, error) {
	var out []foundFile
	for _, root := range roots {
		info, err := os.Lstat(root)
		if err != nil {
			return nil, fmt.Errorf("file or directory could not be read: %s", root)
		}
		if info.Mode()&os.ModeSymlink != 0 {
			target, err := os.Stat(root)
			if err != nil {
				return nil, fmt.Errorf("file or directory could not be read: %s", root)
			}
			if !cfg.includeSyms && !target.IsDir() {
				continue
			}
			info = target
		}
		if !info.IsDir() {
			out = append(out, foundFile{location: root, filename: root, direct: true})
			continue
		}
		cleanRoot := filepath.Clean(root)
		matcher := &ignoreMatcher{}
		var modules []string
		if cfg.useGitmodules {
			modules = readGitmodules(cleanRoot)
		}
		cfg.walkDir(cleanRoot, "", matcher, modules, &out)
	}
	return out, nil
}

func (cfg *walkConfig) walkDir(root, rel string, parent *ignoreMatcher, modules []string, out *[]foundFile) {
	dir := root
	if rel != "" {
		dir = filepath.Join(root, rel)
	}
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	matcher := parent
	// load ignore files in this directory
	names := map[string]bool{}
	for _, e := range entries {
		names[e.Name()] = true
	}
	loadIgnore := func(name string) {
		content, err := os.ReadFile(filepath.Join(dir, name))
		if err != nil {
			return
		}
		if matcher == parent {
			matcher = parent.clone()
		}
		matcher.addRules(rel, string(content))
	}
	if cfg.useGitignore && names[".gitignore"] {
		loadIgnore(".gitignore")
	}
	if cfg.useIgnore && names[".ignore"] {
		loadIgnore(".ignore")
	}
	if cfg.useSccIgnore && names[".sccignore"] {
		loadIgnore(".sccignore")
	}
	sort.Slice(entries, func(i, j int) bool { return entries[i].Name() < entries[j].Name() })
	for _, e := range entries {
		name := e.Name()
		childRel := name
		if rel != "" {
			childRel = rel + "/" + name
		}
		fullPath := filepath.Join(root, childRel)
		if root == "." {
			fullPath = childRel
		}
		isDir := e.IsDir()
		symloc := ""
		if e.Type()&os.ModeSymlink != 0 {
			if !cfg.includeSyms {
				continue
			}
			target, err := os.Stat(fullPath)
			if err != nil {
				continue
			}
			if target.IsDir() {
				continue
			}
			isDir = false
			if t, err := os.Readlink(fullPath); err == nil {
				symloc = t
			}
		}
		if isDir {
			if cfg.dirExcluded(fullPath, name) {
				continue
			}
			excludedModule := false
			for _, m := range modules {
				if filepath.Clean(m) == childRel {
					excludedModule = true
					break
				}
			}
			if excludedModule {
				continue
			}
			if matcher.matches(childRel, true) {
				continue
			}
			cfg.walkDir(root, childRel, matcher, modules, out)
			continue
		}
		if !e.Type().IsRegular() && symloc == "" {
			continue
		}
		if name == ".gitignore" || name == ".ignore" {
			if !cfg.countIgnore {
				continue
			}
		}
		if name == ".sccignore" {
			continue
		}
		if cfg.fileExcluded(fullPath, name) {
			continue
		}
		if matcher.matches(childRel, false) {
			continue
		}
		*out = append(*out, foundFile{location: fullPath, filename: name, symloc: symloc})
	}
}
