cd /workspace && cat > scc.go <<'EOF'
package main

import (
	"fmt"
	"os"
	"path/filepath"
	"runtime"
	"sort"
	"strings"
	"sync"
	"time"
)

// LanguageSummary aggregates the results for one language.
type LanguageSummary struct {
	Name               string
	Bytes              int64
	CodeBytes          int64
	Lines              int64
	Code               int64
	Comment            int64
	Blank              int64
	Complexity         int64
	Count              int64
	WeightedComplexity float64
	Files              []*FileJob
	LineLength         []int
	ULOC               int
	uniqueLines        map[string]struct{}
	complexityPerLines float64
}

type remapRule struct {
	key  []byte
	lang string
}

type runState struct {
	startTime    time.Time
	remapUnknown []remapRule
	remapAll     []remapRule
	whitelist    map[string]bool
	blacklist    map[string]bool
	hasWhitelist bool
	hasBlacklist bool
	totalULOC    int
	dirFilePaths []string
}

var state runState

func printError(msg string) {
	if opts.Verbose || opts.Debug || opts.Trace {
		fmt.Fprintf(os.Stderr, "ERROR %s: %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), msg)
	}
}

func printWarn(msg string) {
	if opts.Verbose || opts.Debug || opts.Trace {
		fmt.Fprintf(os.Stderr, "WARN %s: %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), msg)
	}
}

func printDebug(msg string) {
	if opts.Debug || opts.Trace {
		fmt.Fprintf(os.Stderr, "DEBUG %s: %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), msg)
	}
}

func printTrace(msg string) {
	if opts.Trace {
		fmt.Fprintf(os.Stderr, "TRACE %s: %s\n", time.Now().UTC().Format("2006-01-02T15:04:05Z"), msg)
	}
}

func parseRemap(value string) []remapRule {
	var rules []remapRule
	if value == "" {
		return rules
	}
	for _, part := range strings.Split(value, ",") {
		idx := strings.LastIndex(part, ":")
		if idx <= 0 {
			continue
		}
		key := part[:idx]
		lang := part[idx+1:]
		if key == "" || lang == "" {
			continue
		}
		rules = append(rules, remapRule{key: []byte(key), lang: lang})
	}
	return rules
}

func applyCountAs() {
	if opts.CountAs == "" {
		return
	}
	for _, part := range strings.Split(opts.CountAs, ",") {
		idx := strings.Index(part, ":")
		if idx <= 0 {
			continue
		}
		ext := part[:idx]
		lang := part[idx+1:]
		if lang == "" {
			continue
		}
		target := ""
		if name, ok := canonicalLanguageName(lang); ok {
			target = name
		} else if langs, ok := ExtensionToLanguage[strings.ToLower(lang)]; ok && len(langs) > 0 {
			target = langs[0]
		} else {
			target = lang
		}
		ExtensionToLanguage[strings.ToLower(ext)] = []string{target}
	}
}

func setupOptions() {
	if opts.Wide {
		opts.Format = "wide"
	}
	if opts.Dryness {
		opts.Uloc = true
	}
	if opts.NoGen {
		opts.Gen = true
	}
	if opts.NoMin {
		opts.Min = true
	}
	if opts.NoMinGen {
		opts.MinGen = true
	}
	if opts.MinGen {
		opts.Min = true
		opts.Gen = true
	}
	state.whitelist = map[string]bool{}
	for _, e := range opts.IncludeExt {
		if e != "" {
			state.whitelist[e] = true
		}
	}
	state.hasWhitelist = len(state.whitelist) > 0
	state.blacklist = map[string]bool{}
	for _, e := range opts.ExcludeExt {
		if e != "" {
			state.blacklist[e] = true
		}
	}
	state.hasBlacklist = len(state.blacklist) > 0
	state.remapUnknown = parseRemap(opts.RemapUnknown)
	state.remapAll = parseRemap(opts.RemapAll)
	applyCountAs()
}

func debugOptions() {
	printDebug(fmt.Sprintf("Path Deny List: %v", opts.ExcludeDir))
	printDebug(fmt.Sprintf("Sort By: %s", opts.Sort))
	printDebug(fmt.Sprintf("White List: %v", opts.IncludeExt))
	printDebug(fmt.Sprintf("Files Output: %t", opts.ByFile))
	printDebug(fmt.Sprintf("Verbose: %t", opts.Verbose))
	printDebug(fmt.Sprintf("Duplicates Detection: %t", opts.NoDuplicates))
	printDebug(fmt.Sprintf("Complexity Calculation: %t", !opts.NoComplexity))
	printDebug(fmt.Sprintf("Wide: %t", opts.Wide))
	printDebug(fmt.Sprintf("Average Wage: %d", opts.AvgWage))
	printDebug(fmt.Sprintf("Cocomo: %t", !opts.NoCocomo))
	printDebug(fmt.Sprintf("Locomo: %t", opts.Locomo))
	printDebug(fmt.Sprintf("Minified/Generated Detection: %t/%t", opts.Min, opts.Gen))
	printDebug(fmt.Sprintf("Ignore Minified/Generated: %t/%t", opts.NoMin, opts.NoGen))
	printDebug(fmt.Sprintf("IncludeSymLinks: %t", opts.IncludeSymlinks))
	printDebug(fmt.Sprintf("Uloc: %t", opts.Uloc))
	printDebug(fmt.Sprintf("Dryness: %t", opts.Dryness))
	printDebug(fmt.Sprintf("NumCPU: %d", runtime.NumCPU()))
	printDebug(fmt.Sprintf("SortBy: %s", opts.Sort))
	printDebug(fmt.Sprintf("PathDenyList: %v", opts.ExcludeDir))
}

func run(args []string) {
	state.startTime = time.Now()
	setupOptions()
	debugOptions()

	roots := args
	if len(roots) == 0 {
		roots = []string{"."}
	}
	state.dirFilePaths = roots

	cfg := newWalkConfig()
	files, err := walk(roots, cfg)
	if err != nil {
		fmt.Println(err.Error())
		os.Exit(1)
	}

	// Determine languages and read files
	jobs := make([]*FileJob, 0, len(files))
	for _, f := range files {
		job := prepareJob(f)
		if job != nil {
			jobs = append(jobs, job)
		}
	}

	// process concurrently
	workers := runtime.NumCPU()
	if workers > 64 {
		workers = 64
	}
	if workers < 1 {
		workers = 1
	}
	var wg sync.WaitGroup
	ch := make(chan *FileJob)
	for w := 0; w < workers; w++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for job := range ch {
				processJob(job)
			}
		}()
	}
	for _, j := range jobs {
		ch <- j
	}
	close(ch)
	wg.Wait()

	printDebug(fmt.Sprintf("milliseconds reading files into memory: %d", time.Since(state.startTime).Milliseconds()))

	// filter and aggregate
	summaries := aggregate(jobs)
	sortSummaries(summaries)

	output := formatOutput(summaries)
	writeOutput(output)
}

// prepareJob decides the language for a found file, returning nil if it should be skipped.
func prepareJob(f foundFile) *FileJob {
	name := f.filename
	if f.direct {
		name = filepath.Base(f.location)
	}
	var langs []string
	var ext string
	if state.hasWhitelist {
		langs, ext = detectByExtension(name)
		if !state.whitelist[ext] {
			return nil
		}
	} else {
		langs, ext = DetectLanguage(name)
	}
	if state.hasBlacklist && state.blacklist[ext] {
		return nil
	}
	job := &FileJob{Filename: f.filename, Location: f.location, Extension: ext, Symlocation: f.symloc}
	if f.direct {
		job.Filename = f.location
	}
	if len(langs) == 0 {
		if !hasRealExtension(name) && !state.hasWhitelist {
			printWarn("possible #! file: " + name)
			job.PossibleLanguages = []string{"#!"}
			job.Extension = name
			job.needsShebang = true
			return job
		}
		printWarn("skipping file unknown extension: " + name)
		return nil
	}
	job.PossibleLanguages = langs
	if len(langs) == 1 {
		job.Language = langs[0]
	}
	return job
}

func checkRemap(content []byte, rules []remapRule) (string, bool) {
	head := content
	if len(head) > 1000 {
		head = head[:1000]
	}
	for _, r := range rules {
		if bytesContains(head, r.key) {
			return r.lang, true
		}
	}
	return "", false
}

func bytesContains(b, sub []byte) bool {
	return strings.Contains(string(b), string(sub))
}

func processJob(job *FileJob) {
	content, err := os.ReadFile(job.Location)
	if err != nil {
		printError(fmt.Sprintf("error reading file %s: %s", job.Location, err.Error()))
		job.skip = true
		return
	}
	job.Content = content
	job.Bytes = int64(len(content))

	if job.needsShebang {
		if lang, ok := checkRemap(content, state.remapUnknown); ok {
			job.Language = lang
		} else if lang, ok := DetectSheBang(content); ok {
			printWarn("detected #! " + lang + " for " + job.Filename)
			job.Language = lang
		} else {
			printWarn("unable to determine #! language for " + job.Filename)
			job.skip = true
			return
		}
	} else if job.Language == "" {
		job.Language = DetermineLanguage(job.PossibleLanguages[0], job.PossibleLanguages, content)
	}
	if len(state.remapAll) > 0 {
		if lang, ok := checkRemap(content, state.remapAll); ok {
			job.Language = lang
		}
	}
	feat := LanguageFeatures[job.Language]
	if feat == nil {
		if name, ok := canonicalLanguageName(job.Language); ok {
			job.Language = name
			feat = LanguageFeatures[name]
		}
	}
	if feat == nil {
		job.skip = true
		return
	}

	CountStats(job, feat, !opts.NoComplexity)
	if job.Binary && !opts.Binary {
		printWarn("skipping file identified as binary: " + job.Filename)
		job.skip = true
		return
	}
	if job.Binary {
		// binary detection disabled, count fully ignoring the marker
		job.Binary = false
		job.Lines, job.Code, job.Comment, job.Blank, job.Complexity = 0, 0, 0, 0, 0
		countStatsIgnoringBinary(job, feat, !opts.NoComplexity)
	}
	if opts.Gen {
		checkGenerated(job, opts.GeneratedMarkers)
	}
	if opts.Min && !job.Generated {
		checkMinified(job, opts.MinGenLineLength)
	}
	if opts.NoDuplicates {
		computeHash(job)
	}
	if opts.Uloc {
		computeUniqueLines(job)
	}
	if opts.Character {
		computeLineLengths(job)
	}
	if opts.Trace {
		printTrace(fmt.Sprintf("%s lines=%d code=%d comment=%d blank=%d complexity=%d", job.Location, job.Lines, job.Code, job.Comment, job.Blank, job.Complexity))
	}
	job.Content = nil
}

func countStatsIgnoringBinary(job *FileJob, feat *LanguageFeature, complexity bool) {
	saved := job.Content
	// replace NUL bytes so the detection cannot trigger
	cp := make([]byte, len(saved))
	copy(cp, saved)
	for i := range cp {
		if cp[i] == 0 {
			cp[i] = 1
		}
	}
	job.Content = cp
	CountStats(job, feat, complexity)
	job.Content = saved
	job.Binary = false
}

func aggregate(jobs []*FileJob) []*LanguageSummary {
	byName := map[string]*LanguageSummary{}
	var order []string
	seenHash := map[string]bool{}
	var totalUnique map[string]struct{}
	if opts.Uloc {
		totalUnique = map[string]struct{}{}
	}
	for _, job := range jobs {
		if job.skip {
			continue
		}
		if opts.NoDuplicates {
			h := hashString(job.Hash)
			if seenHash[h] {
				printWarn("skipping duplicate file: " + job.Filename)
				continue
			}
			seenHash[h] = true
		}
		if opts.NoLarge && (job.Bytes >= opts.LargeByteCount || job.Lines >= opts.LargeLineCount) {
			printWarn("skipping large file: " + job.Filename)
			continue
		}
		if opts.NoMin && job.Minified {
			printWarn("skipping minified file: " + job.Filename)
			continue
		}
		if opts.NoGen && job.Generated {
			printWarn("skipping generated file: " + job.Filename)
			continue
		}
		if opts.NoMinGen && (job.Minified || job.Generated) {
			continue
		}
		s, ok := byName[job.Language]
		if !ok {
			s = &LanguageSummary{Name: job.Language}
			if opts.Uloc {
				s.uniqueLines = map[string]struct{}{}
			}
			byName[job.Language] = s
			order = append(order, job.Language)
		}
		s.Bytes += job.Bytes
		s.Lines += job.Lines
		s.Code += job.Code
		s.Comment += job.Comment
		s.Blank += job.Blank
		s.Complexity += job.Complexity
		s.Count++
		if job.Code > 0 {
			s.complexityPerLines += float64(job.Complexity) / float64(job.Code) * 100
		}
		s.Files = append(s.Files, job)
		if opts.Uloc {
			for l := range job.UniqueLines {
				s.uniqueLines[l] = struct{}{}
				totalUnique[l] = struct{}{}
			}
		}
		if opts.Character {
			s.LineLength = append(s.LineLength, job.LineLength...)
		}
		job.UniqueLines = nil
	}
	out := make([]*LanguageSummary, 0, len(order))
	for _, n := range order {
		s := byName[n]
		if opts.Uloc {
			s.ULOC = len(s.uniqueLines)
			s.uniqueLines = nil
		}
		out = append(out, s)
	}
	if opts.Uloc {
		state.totalULOC = len(totalUnique)
	}
	return out
}

func sortSummaries(summaries []*LanguageSummary) {
	sortBy := strings.ToLower(opts.Sort)
	less := func(a, b *LanguageSummary) bool {
		switch sortBy {
		case "name":
			return a.Name < b.Name
		case "lines":
			if a.Lines != b.Lines {
				return a.Lines > b.Lines
			}
		case "blanks":
			if a.Blank != b.Blank {
				return a.Blank > b.Blank
			}
		case "code":
			if a.Code != b.Code {
				return a.Code > b.Code
			}
		case "comments":
			if a.Comment != b.Comment {
				return a.Comment > b.Comment
			}
		case "complexity":
			if a.Complexity != b.Complexity {
				return a.Complexity > b.Complexity
			}
		default:
			if a.Count != b.Count {
				return a.Count > b.Count
			}
		}
		return a.Name < b.Name
	}
	sort.SliceStable(summaries, func(i, j int) bool { return less(summaries[i], summaries[j]) })
	for _, s := range summaries {
		files := s.Files
		fless := func(a, b *FileJob) bool {
			switch sortBy {
			case "name":
				return a.Location < b.Location
			case "blanks":
				if a.Blank != b.Blank {
					return a.Blank > b.Blank
				}
			case "code":
				if a.Code != b.Code {
					return a.Code > b.Code
				}
			case "comments":
				if a.Comment != b.Comment {
					return a.Comment > b.Comment
				}
			case "complexity":
				if a.Complexity != b.Complexity {
					return a.Complexity > b.Complexity
				}
			default:
				if a.Lines != b.Lines {
					return a.Lines > b.Lines
				}
			}
			return a.Location < b.Location
		}
		sort.SliceStable(files, func(i, j int) bool { return fless(files[i], files[j]) })
	}
}

func writeOutput(output string) {
	if opts.FormatMulti != "" {
		return
	}
	if opts.Output == "" {
		fmt.Print(output)
		return
	}
	if err := os.WriteFile(opts.Output, []byte(output), 0644); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
	}
}
