package main

import (
	"fmt"
	"math"
	"strconv"
	"strings"
)

type cocomoParams struct {
	name string
	a, b float64
	c, d float64
}

func cocomoProjectParams() cocomoParams {
	switch strings.ToLower(opts.CocomoProjectType) {
	case "semi-detached":
		return cocomoParams{"semi-detached", 3.0, 1.12, 2.5, 0.35}
	case "embedded":
		return cocomoParams{"embedded", 3.6, 1.20, 2.5, 0.32}
	}
	if strings.HasPrefix(strings.ToLower(opts.CocomoProjectType), "custom") {
		parts := strings.Split(opts.CocomoProjectType, ",")
		if len(parts) == 5 {
			vals := make([]float64, 4)
			ok := true
			for i := 0; i < 4; i++ {
				v, err := strconv.ParseFloat(strings.TrimSpace(parts[i+1]), 64)
				if err != nil {
					ok = false
					break
				}
				vals[i] = v
			}
			if ok {
				return cocomoParams{opts.CocomoProjectType, vals[0], vals[1], vals[2], vals[3]}
			}
		}
	}
	return cocomoParams{"organic", 2.4, 1.05, 2.5, 0.38}
}

func estimateEffort(sloc int64, p cocomoParams) float64 {
	return p.a * math.Pow(float64(sloc)/1000, p.b) * opts.EAF
}

func estimateCost(effort float64) float64 {
	return effort * (float64(opts.AvgWage) / 12) * opts.Overhead
}

func estimateScheduleMonths(effort float64, p cocomoParams) float64 {
	return p.c * math.Pow(effort, p.d)
}

type cocomoResult struct {
	effort   float64
	cost     float64
	schedule float64
	people   float64
	params   cocomoParams
}

func calculateCocomo(sloc int64) cocomoResult {
	p := cocomoProjectParams()
	effort := estimateEffort(sloc, p)
	cost := estimateCost(effort)
	schedule := estimateScheduleMonths(effort, p)
	people := effort / schedule
	if sloc == 0 {
		return cocomoResult{0, 0, 0, 0, p}
	}
	return cocomoResult{effort, cost, schedule, people, p}
}

