package main

import (
	"encoding/json"
	"fmt"
	"math"
	"os"
	"path/filepath"
	"strings"
	"time"
	"unicode/utf8"
)

const (
	tabularWidth = 79
	wideWidth    = 109
)

func sepChar() string {
	if opts.CI {
		return "-"
	}
	return "─"
}

func totals(summaries []*LanguageSummary) (files, lines, code, comment, blank, complexity, bytes int64, cpl float64) {
	for _, s := range summaries {
		files += s.Count
		lines += s.Lines
		code += s.Code
		comment += s.Comment
		blank += s.Blank
		complexity += s.Complexity
		bytes += s.Bytes
		cpl += s.complexityPerLines
	}
	return
}

func trimName(name string, max int) string {
	if utf8.RuneCountInString(name) > max {
		return name[:max-1] + "…"
	}
	return name
}

func trimPath(name string, max int) string {
	if len(name) > max {
		return "~" + name[len(name)-(max-1):]
	}
	return name
}

func pct(part, whole int64) string {
	if whole == 0 {
		return "0.0%"
	}
	return fmt.Sprintf("%.1f%%", float64(part)/float64(whole)*100)
}

func maxMean(lengths []int) (int, int) {
	max := 0
	sum := 0
	for _, l := range lengths {
		if l > max {
			max = l
		}
		sum += l
	}
	if len(lengths) == 0 {
		return 0, 0
	}
	return max, sum / len(lengths)
}

func formatSize(bytes int64) string {
	var val float64
	unit := strings.ToUpper(opts.SizeUnit)
	switch strings.ToLower(opts.SizeUnit) {
	case "binary":
		val = float64(bytes) / 1024 / 1024
	case "mixed":
		val = float64(bytes) / 1000 / 1024
	case "xkcd-kb":
		return fmt.Sprintf("Processed %d bytes, 0.000 megabytes (%s)", bytes, unit)
	case "xkcd-kelly":
		val = float64(bytes) / 1012 / 1012
	case "xkcd-imaginary":
		return fmt.Sprintf("Processed %d bytes, ¯\\_(ツ)_/¯ megabytes (%s)", bytes, unit)
	case "xkcd-intel":
		val = float64(bytes) / 1023.937528 / 1023.937528
	case "xkcd-drive":
		kb := 908.0 - 4*float64(time.Now().Year()-2013)
		val = float64(bytes) / kb / kb
	case "xkcd-bakers":
		val = float64(bytes) / 1152 / 1152
	default:
		unit = "SI"
		val = float64(bytes) / 1000 / 1000
	}
	return fmt.Sprintf("Processed %d bytes, %.3f megabytes (%s)", bytes, val, unit)
}

type tableWriter struct {
	sb    strings.Builder
	width int
}

func (t *tableWriter) sep() {
	if opts.NoHBorder {
		return
	}
	t.sb.WriteString(strings.Repeat(sepChar(), t.width))
	t.sb.WriteString("\n")
}

func (t *tableWriter) line(s string) {
	t.sb.WriteString(s)
	t.sb.WriteString("\n")
}

func formatTabular(summaries []*LanguageSummary) string {
	t := &tableWriter{width: tabularWidth}
	noCx := opts.NoComplexity
	files, lines, code, comment, blank, complexity, bytes, _ := totals(summaries)

	langRow := func(name, f, l, b, c, co, cx string) string {
		if noCx {
			return fmt.Sprintf("%-26s %6s %11s %10s %11s %10s", name, f, l, b, c, co)
		}
		return fmt.Sprintf("%-18s %6s %11s %9s %9s %10s %10s", name, f, l, b, c, co, cx)
	}
	fileRow := func(name, l, b, c, co, cx string) string {
		if noCx {
			return fmt.Sprintf("%-33s%11s%11s%12s%11s", name, l, b, c, co)
		}
		return fmt.Sprintf("%-27s%10s%10s%10s%11s%11s", name, l, b, c, co, cx)
	}
	t.sep()
	t.line(langRow("Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity"))
	t.sep()
	for _, s := range summaries {
		t.line(langRow(trimName(s.Name, 15), commaInt(s.Count), commaInt(s.Lines), commaInt(s.Blank), commaInt(s.Comment), commaInt(s.Code), commaInt(s.Complexity)))
		if opts.Percent {
			t.line(langRow("Percentage", pct(s.Count, files), pct(s.Lines, lines), pct(s.Blank, blank), pct(s.Comment, comment), pct(s.Code, code), pct(s.Complexity, complexity)))
		}
		if opts.Character {
			mx, mean := maxMean(s.LineLength)
			t.line(langRow("MaxLine / MeanLine", commaInt(int64(mx)), commaInt(int64(mean)), "", "", "", ""))
		}
		if opts.Uloc && !opts.ByFile {
			t.line(langRow("(ULOC)", "", commaInt(int64(s.ULOC)), "", "", "", ""))
		}
		if opts.ByFile {
			t.sep()
			for _, f := range s.Files {
				t.line(fileRow(trimPath(f.Location, 27), commaInt(f.Lines), commaInt(f.Blank), commaInt(f.Comment), commaInt(f.Code), commaInt(f.Complexity)))
			}
			if opts.Uloc {
				t.line(langRow("(ULOC)", "", commaInt(int64(s.ULOC)), "", "", "", ""))
			}
			t.sep()
		}
	}
	if !opts.ByFile {
		t.sep()
	}
	t.line(langRow("Total", commaInt(files), commaInt(lines), commaInt(blank), commaInt(comment), commaInt(code), commaInt(complexity)))
	t.sep()
	if opts.Uloc {
		t.line(fmt.Sprintf("%-27s%10s", "Unique Lines of Code (ULOC)", commaInt(int64(state.totalULOC))))
		if opts.Dryness {
			dry := 0.0
			if lines > 0 {
				dry = float64(state.totalULOC) / float64(lines)
			}
			t.line(fmt.Sprintf("%-27s%10s", "DRYness %", fmt.Sprintf("%.2f", dry)))
		}
		t.sep()
	}
	if !opts.NoCocomo {
		if opts.SloccountFormat {
			for _, l := range sloccountLines(code) {
				t.line(l)
			}
		} else {
			for _, l := range cocomoLines(code) {
				t.line(l)
			}
		}
		t.sep()
	}
	if opts.Locomo || opts.CostComparison {
		for _, l := range locomoLines(code, complexity) {
			t.line(l)
		}
		t.sep()
	}
	if !opts.NoSize {
		t.line(formatSize(bytes))
		t.sep()
	}
	return t.sb.String()
}

func formatWide(summaries []*LanguageSummary) string {
	t := &tableWriter{width: wideWidth}
	files, lines, code, comment, blank, complexity, bytes, cpl := totals(summaries)
	langRow := func(name, f, l, b, c, co, cx, cl string) string {
		return fmt.Sprintf("%-37s %5s %9s %8s %9s %8s %10s %16s", name, f, l, b, c, co, cx, cl)
	}
	fileRow := func(name, l, b, c, co, cx, cl string) string {
		return fmt.Sprintf("%-43s%10s%9s%10s%9s%11s%17s", name, l, b, c, co, cx, cl)
	}
	num := func(n int64) string { return fmt.Sprintf("%d", n) }
	t.sep()
	t.line(langRow("Language", "Files", "Lines", "Blanks", "Comments", "Code", "Complexity", "Complexity/Lines"))
	t.sep()
	for _, s := range summaries {
		t.line(langRow(trimName(s.Name, 22), num(s.Count), num(s.Lines), num(s.Blank), num(s.Comment), num(s.Code), num(s.Complexity), fmt.Sprintf("%.2f", s.complexityPerLines)))
		if opts.Percent {
			t.line(langRow("Percentage", pct(s.Count, files), pct(s.Lines, lines), pct(s.Blank, blank), pct(s.Comment, comment), pct(s.Code, code), pct(s.Complexity, complexity), ""))
		}
		if opts.Character {
			mx, mean := maxMean(s.LineLength)
			t.line(langRow("MaxLine / MeanLine", num(int64(mx)), num(int64(mean)), "", "", "", "", ""))
		}
		if opts.Uloc {
			t.line(langRow("(ULOC)", "", num(int64(s.ULOC)), "", "", "", "", ""))
		}
		if opts.ByFile {
			t.sep()
			for _, f := range s.Files {
				cl := 0.0
				if f.Code > 0 {
					cl = float64(f.Complexity) / float64(f.Code) * 100
				}
				t.line(fileRow(trimPath(f.Location, 43), num(f.Lines), num(f.Blank), num(f.Comment), num(f.Code), num(f.Complexity), fmt.Sprintf("%.2f", cl)))
			}
			t.sep()
		}
	}
	if !opts.ByFile {
		t.sep()
	}
	t.line(langRow("Total", num(files), num(lines), num(blank), num(comment), num(code), num(complexity), fmt.Sprintf("%.2f", cpl)))
	t.sep()
	if opts.Uloc {
		t.line(fmt.Sprintf("%-43s%10s", "Unique Lines of Code (ULOC)", num(int64(state.totalULOC))))
		if opts.Dryness {
			dry := 0.0
			if lines > 0 {
				dry = float64(state.totalULOC) / float64(lines)
			}
			t.line(fmt.Sprintf("%-43s%10s", "DRYness %", fmt.Sprintf("%.2f", dry)))
		}
		t.sep()
	}
	if !opts.NoCocomo {
		if opts.SloccountFormat {
			for _, l := range sloccountLines(code) {
				t.line(l)
			}
		} else {
			for _, l := range cocomoLines(code) {
				t.line(l)
			}
		}
	}
	if opts.Locomo || opts.CostComparison {
		for _, l := range locomoLines(code, complexity) {
			t.line(l)
		}
	}
	if !opts.NoSize {
		t.line(formatSize(bytes))
	}
	if !opts.NoCocomo || opts.Locomo || opts.CostComparison || !opts.NoSize {
		t.sep()
	}
	return t.sb.String()
}

// JSON structures matching the original field order.
type jsonFile struct {
	Language           string      `json:"Language"`
	PossibleLanguages  []string    `json:"PossibleLanguages"`
	Filename           string      `json:"Filename"`
	Extension          string      `json:"Extension"`
	Location           string      `json:"Location"`
	Symlocation        string      `json:"Symlocation"`
	Bytes              int64       `json:"Bytes"`
	Lines              int64       `json:"Lines"`
	Code               int64       `json:"Code"`
	Comment            int64       `json:"Comment"`
	Blank              int64       `json:"Blank"`
	Complexity         int64       `json:"Complexity"`
	WeightedComplexity float64     `json:"WeightedComplexity"`
	Hash               interface{} `json:"Hash"`
	Binary             bool        `json:"Binary"`
	Minified           bool        `json:"Minified"`
	Generated          bool        `json:"Generated"`
	EndPoint           int         `json:"EndPoint"`
	Uloc               int         `json:"Uloc"`
}

type jsonLanguage struct {
	Name               string     `json:"Name"`
	Bytes              int64      `json:"Bytes"`
	CodeBytes          int64      `json:"CodeBytes"`
	Lines              int64      `json:"Lines"`
	Code               int64      `json:"Code"`
	Comment            int64      `json:"Comment"`
	Blank              int64      `json:"Blank"`
	Complexity         int64      `json:"Complexity"`
	Count              int64      `json:"Count"`
	WeightedComplexity float64    `json:"WeightedComplexity"`
	Files              []jsonFile `json:"Files"`
	LineLength         []int      `json:"LineLength"`
	ULOC               int        `json:"ULOC"`
}

func toJSONLanguages(summaries []*LanguageSummary) []jsonLanguage {
	out := make([]jsonLanguage, 0, len(summaries))
	for _, s := range summaries {
		jl := jsonLanguage{Name: s.Name, Bytes: s.Bytes, Lines: s.Lines, Code: s.Code, Comment: s.Comment, Blank: s.Blank, Complexity: s.Complexity, Count: s.Count, Files: []jsonFile{}, ULOC: s.ULOC}
		if opts.ByFile {
			for _, f := range s.Files {
				jf := jsonFile{Language: f.Language, PossibleLanguages: f.PossibleLanguages, Filename: f.Filename, Extension: f.Extension, Location: f.Location, Symlocation: f.Symlocation, Bytes: f.Bytes, Lines: f.Lines, Code: f.Code, Comment: f.Comment, Blank: f.Blank, Complexity: f.Complexity, Binary: f.Binary, Minified: f.Minified, Generated: f.Generated, Uloc: f.Uloc}
				if f.PossibleLanguages == nil {
					jf.PossibleLanguages = []string{}
				}
				if opts.NoDuplicates {
					jf.Hash = map[string]interface{}{}
				}
				jl.Files = append(jl.Files, jf)
			}
		}
		out = append(out, jl)
	}
	return out
}

func formatJSON(summaries []*LanguageSummary) string {
	b, _ := json.Marshal(toJSONLanguages(summaries))
	return string(b)
}

func formatJSON2(summaries []*LanguageSummary) string {
	_, _, code, _, _, complexity, _, _ := totals(summaries)
	r := calculateCocomo(code)
	m := map[string]interface{}{}
	var sb strings.Builder
	langs, _ := json.Marshal(toJSONLanguages(summaries))
	sb.WriteString("{\"languageSummary\":")
	sb.Write(langs)
	writeF := func(key string, v float64) {
		b, _ := json.Marshal(v)
		sb.WriteString(",\"" + key + "\":" + string(b))
	}
	writeF("estimatedCost", r.cost)
	writeF("estimatedScheduleMonths", r.schedule)
	writeF("estimatedPeople", r.people)
	if opts.Locomo || opts.CostComparison {
		l := calculateLocomo(code, complexity)
		writeF("estimatedLLMCost", l.cost)
		writeF("estimatedLLMInputTokens", l.inputTokens)
		writeF("estimatedLLMOutputTokens", l.outputTokens)
		writeF("estimatedLLMGenerationSeconds", l.generationSeconds)
		writeF("estimatedLLMReviewHours", l.reviewHours)
		p, _ := json.Marshal(l.preset)
		sb.WriteString(",\"estimatedLLMPreset\":" + string(p))
		writeF("estimatedLLMAverageComplexityMultiplier", l.multiplier)
		writeF("estimatedLLMCycles", l.cycles)
	}
	_ = m
	sb.WriteString("}")
	return sb.String()
}

func csvEscape(s string) string {
	if strings.ContainsAny(s, ",\"\n\r") {
		return "\"" + strings.ReplaceAll(s, "\"", "\"\"") + "\""
	}
	return s
}

func formatCSV(summaries []*LanguageSummary) string {
	var sb strings.Builder
	if opts.ByFile {
		sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,ULOC\n")
		for _, s := range summaries {
			for _, f := range s.Files {
				sb.WriteString(fmt.Sprintf("%s,%s,%s,%d,%d,%d,%d,%d,%d,%d\n", csvEscape(f.Language), csvEscape(f.Location), csvEscape(f.Filename), f.Lines, f.Code, f.Comment, f.Blank, f.Complexity, f.Bytes, f.Uloc))
			}
		}
		return sb.String()
	}
	sb.WriteString("Language,Lines,Code,Comments,Blanks,Complexity,Bytes,Files,ULOC\n")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("%s,%d,%d,%d,%d,%d,%d,%d,%d\n", csvEscape(s.Name), s.Lines, s.Code, s.Comment, s.Blank, s.Complexity, s.Bytes, s.Count, s.ULOC))
	}
	return sb.String()
}

func formatCSVStream(summaries []*LanguageSummary) string {
	var sb strings.Builder
	sb.WriteString("Language,Provider,Filename,Lines,Code,Comments,Blanks,Complexity,Bytes,Uloc\n")
	for _, s := range summaries {
		for _, f := range s.Files {
			sb.WriteString(fmt.Sprintf("%s,%q,%q,%d,%d,%d,%d,%d,%d,%d\n", f.Language, f.Location, f.Filename, f.Lines, f.Code, f.Comment, f.Blank, f.Complexity, f.Bytes, f.Uloc))
		}
	}
	return sb.String()
}

func formatClocYAML(summaries []*LanguageSummary) string {
	files, lines, code, comment, blank, _, _, _ := totals(summaries)
	elapsed := time.Since(state.startTime).Seconds()
	var sb strings.Builder
	sb.WriteString("# https://github.com/boyter/scc/\n")
	sb.WriteString("header:\n")
	sb.WriteString("  url: https://github.com/boyter/scc/\n")
	sb.WriteString("  version: " + Version + "\n")
	sb.WriteString(fmt.Sprintf("  elapsed_seconds: %.3f\n", elapsed))
	sb.WriteString(fmt.Sprintf("  n_files: %d\n", files))
	sb.WriteString(fmt.Sprintf("  n_lines: %d\n", lines))
	fps := 0.0
	lps := 0.0
	if elapsed > 0 {
		fps = float64(files) / elapsed
		lps = float64(lines) / elapsed
	}
	sb.WriteString(fmt.Sprintf("  files_per_second: %v\n", math.Round(fps*1000)/1000))
	sb.WriteString(fmt.Sprintf("  lines_per_second: %v\n", math.Round(lps*1000)/1000))
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				sb.WriteString(f.Location + ":\n")
				sb.WriteString("  name: " + f.Location + "\n")
				sb.WriteString(fmt.Sprintf("  code: %d\n", f.Code))
				sb.WriteString(fmt.Sprintf("  comment: %d\n", f.Comment))
				sb.WriteString(fmt.Sprintf("  blank: %d\n", f.Blank))
				sb.WriteString("  language: " + f.Language + "\n")
			}
		}
	} else {
		for _, s := range summaries {
			sb.WriteString(s.Name + ":\n")
			sb.WriteString("  name: " + s.Name + "\n")
			sb.WriteString(fmt.Sprintf("  code: %d\n", s.Code))
			sb.WriteString(fmt.Sprintf("  comment: %d\n", s.Comment))
			sb.WriteString(fmt.Sprintf("  blank: %d\n", s.Blank))
			sb.WriteString(fmt.Sprintf("  nFiles: %d\n", s.Count))
		}
	}
	sb.WriteString("SUM:\n")
	sb.WriteString(fmt.Sprintf("  code: %d\n", code))
	sb.WriteString(fmt.Sprintf("  comment: %d\n", comment))
	sb.WriteString(fmt.Sprintf("  blank: %d\n", blank))
	sb.WriteString(fmt.Sprintf("  nFiles: %d\n", files))
	return sb.String()
}

func formatHTMLTable(summaries []*LanguageSummary) string {
	files, lines, code, comment, blank, complexity, bytes, _ := totals(summaries)
	var sb strings.Builder
	sb.WriteString("<table id=\"scc-table\">\n\t<thead><tr>\n\t\t<th>Language</th>\n\t\t<th>Files</th>\n\t\t<th>Lines</th>\n\t\t<th>Blank</th>\n\t\t<th>Comment</th>\n\t\t<th>Code</th>\n\t\t<th>Complexity</th>\n\t\t<th>Bytes</th>\n\t\t<th>Uloc</th>\n\t</tr></thead>\n\t<tbody>")
	for _, s := range summaries {
		sb.WriteString(fmt.Sprintf("<tr>\n\t\t<th>%s</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>", s.Name, s.Count, s.Lines, s.Blank, s.Comment, s.Code, s.Complexity, s.Bytes, s.ULOC))
		if opts.ByFile {
			for _, f := range s.Files {
				sb.WriteString(fmt.Sprintf("<tr>\n\t\t<td>%s</td>\n\t\t<td></td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t\t<td>%d</td>\n\t</tr>", f.Location, f.Lines, f.Blank, f.Comment, f.Code, f.Complexity, f.Bytes, f.Uloc))
			}
		}
	}
	sb.WriteString("</tbody>\n\t<tfoot><tr>\n\t\t<th>Total</th>\n")
	sb.WriteString(fmt.Sprintf("\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t\t<th>%d</th>\n\t</tr>\n", files, lines, blank, comment, code, complexity, bytes, state.totalULOC))
	if !opts.NoCocomo {
		sb.WriteString("\t<tr>\n\t\t<th colspan=\"9\">")
		for _, l := range cocomoLines(code) {
			sb.WriteString(l + "<br>")
		}
		sb.WriteString("</th>\n\t</tr>")
	}
	sb.WriteString("</tfoot>\n\t</table>")
	return sb.String()
}

func formatHTML(summaries []*LanguageSummary) string {
	return "<html lang=\"en\"><head><meta charset=\"utf-8\" /><title>scc html output</title><style>table { border-collapse: collapse; }td, th { border: 1px solid #999; padding: 0.5rem; text-align: left;}</style></head><body>" + formatHTMLTable(summaries) + "</body></html>\n"
}

func sqlProject() string {
	if opts.SQLProject != "" {
		return opts.SQLProject
	}
	return strings.Join(state.dirFilePaths, ",")
}

func formatSQLInserts(summaries []*LanguageSummary) string {
	_, _, code, _, _, _, _, _ := totals(summaries)
	project := sqlProject()
	var sb strings.Builder
	sb.WriteString("\nbegin transaction;")
	for _, s := range summaries {
		for _, f := range s.Files {
			dir, _ := filepath.Split(f.Location)
			sb.WriteString(fmt.Sprintf("\ninsert into t values('%s', '%s', '%s', '%s', '%s', %d, %d, %d, %d, %d, %d);", project, f.Language, f.Location, dir, f.Filename, f.Bytes, f.Blank, f.Comment, f.Code, f.Complexity, f.Uloc))
		}
	}
	r := calculateCocomo(code)
	elapsed := time.Since(state.startTime).Seconds()
	sb.WriteString("\ncommit;")
	sb.WriteString("\nbegin transaction;")
	sb.WriteString(fmt.Sprintf("\ninsert into metadata values('%s', '%s', %f, %f, %f, %f);", time.Now().Format("2006-01-02 15:04:05"), project, elapsed, r.cost, r.schedule, r.people))
	sb.WriteString("\ncommit;")
	return sb.String()
}

func formatSQL(summaries []*LanguageSummary) string {
	var sb strings.Builder
	sb.WriteString("create table metadata (   -- github.com/boyter/scc v " + Version + "\n")
	sb.WriteString("             timestamp text,\n")
	sb.WriteString("             Project   text,\n")
	sb.WriteString("             elapsed_s real,\n")
	sb.WriteString("             estimated_cost real,\n")
	sb.WriteString("             estimated_schedule_months real,\n")
	sb.WriteString("             estimated_people real);\n")
	sb.WriteString("create table t        (\n")
	sb.WriteString("             Project       text   ,\n")
	sb.WriteString("             Language      text   ,\n")
	sb.WriteString("             File          text   ,\n")
	sb.WriteString("             File_dirname  text   ,\n")
	sb.WriteString("             File_basename text   ,\n")
	sb.WriteString("             nByte         integer,\n")
	sb.WriteString("             nBlank        integer,\n")
	sb.WriteString("             nComment      integer,\n")
	sb.WriteString("             nCode         integer,\n")
	sb.WriteString("             nComplexity   integer,\n")
	sb.WriteString("             nUloc         integer    \n")
	sb.WriteString(");")
	sb.WriteString(formatSQLInserts(summaries))
	return sb.String()
}

func formatOpenMetrics(summaries []*LanguageSummary) string {
	var sb strings.Builder
	sb.WriteString("# TYPE scc_files gauge\n# HELP scc_files Number of sourcecode files.\n")
	sb.WriteString("# TYPE scc_lines gauge\n# HELP scc_lines Number of lines.\n")
	sb.WriteString("# TYPE scc_code gauge\n# HELP scc_code Number of lines of actual code.\n")
	sb.WriteString("# TYPE scc_comments gauge\n# HELP scc_comments Number of comments.\n")
	sb.WriteString("# TYPE scc_blanks gauge\n# HELP scc_blanks Number of blank lines.\n")
	sb.WriteString("# TYPE scc_complexity gauge\n# HELP scc_complexity Code complexity.\n")
	sb.WriteString("# TYPE scc_bytes gauge\n# UNIT scc_bytes bytes\n# HELP scc_bytes Size in bytes.\n")
	if opts.ByFile {
		for _, s := range summaries {
			for _, f := range s.Files {
				lbl := fmt.Sprintf("{language=\"%s\",file=\"%s\"}", f.Language, f.Location)
				sb.WriteString(fmt.Sprintf("scc_lines%s %d\n", lbl, f.Lines))
				sb.WriteString(fmt.Sprintf("scc_code%s %d\n", lbl, f.Code))
				sb.WriteString(fmt.Sprintf("scc_comments%s %d\n", lbl, f.Comment))
				sb.WriteString(fmt.Sprintf("scc_blanks%s %d\n", lbl, f.Blank))
				sb.WriteString(fmt.Sprintf("scc_complexity%s %d\n", lbl, f.Complexity))
				sb.WriteString(fmt.Sprintf("scc_bytes%s %d\n", lbl, f.Bytes))
			}
		}
		sb.WriteString("# EOF\n")
		return sb.String()
	}
	for _, s := range summaries {
		lbl := fmt.Sprintf("{language=\"%s\"}", s.Name)
		sb.WriteString(fmt.Sprintf("scc_files%s %d\n", lbl, s.Count))
		sb.WriteString(fmt.Sprintf("scc_lines%s %d\n", lbl, s.Lines))
		sb.WriteString(fmt.Sprintf("scc_code%s %d\n", lbl, s.Code))
		sb.WriteString(fmt.Sprintf("scc_comments%s %d\n", lbl, s.Comment))
		sb.WriteString(fmt.Sprintf("scc_blanks%s %d\n", lbl, s.Blank))
		sb.WriteString(fmt.Sprintf("scc_complexity%s %d\n", lbl, s.Complexity))
		sb.WriteString(fmt.Sprintf("scc_bytes%s %d\n", lbl, s.Bytes))
	}
	return sb.String()
}

func formatByName(format string, summaries []*LanguageSummary) string {
	switch strings.ToLower(format) {
	case "wide":
		return formatWide(summaries)
	case "json":
		return formatJSON(summaries)
	case "json2":
		return formatJSON2(summaries)
	case "csv":
		return formatCSV(summaries)
	case "csv-stream":
		return formatCSVStream(summaries)
	case "cloc-yaml", "cloc-yml":
		return formatClocYAML(summaries)
	case "html":
		return formatHTML(summaries)
	case "html-table":
		return formatHTMLTable(summaries)
	case "sql":
		return formatSQL(summaries)
	case "sql-insert":
		return formatSQLInserts(summaries)
	case "openmetrics":
		return formatOpenMetrics(summaries)
	}
	return formatTabular(summaries)
}

func formatOutput(summaries []*LanguageSummary) string {
	if opts.FormatMulti != "" {
		for _, part := range strings.Split(opts.FormatMulti, ",") {
			idx := strings.Index(part, ":")
			if idx <= 0 {
				continue
			}
			format := part[:idx]
			dest := part[idx+1:]
			out := formatByName(format, summaries)
			if dest == "stdout" || dest == "" {
				fmt.Print(out)
			} else {
				if err := os.WriteFile(dest, []byte(out), 0644); err != nil {
					fmt.Fprintln(os.Stderr, err.Error())
				}
			}
		}
		return ""
	}
	return formatByName(opts.Format, summaries)
}
