	var sb strings.Builder
	sb.WriteString("<table id=\"scc-table\">\n\t<thead><tr>\n\t\t<th>Language</th>\n\t\t<th>Files</th>\n\t\t<th>Lines</th>\n\t\t<th>Blank</th>\n\t\t<th>Comment</th>\n\t\t<th>Code</th>\n\t\t<th>Complexity</th>\n\t\t<th>Bytes</th>\n\t\t<th>Uloc</th>\n\t</tr></thead>\n\t<tbody>")
