	sb.WriteString("             Language      text   ,\n")
	sb.WriteString("             File          text   ,\n")
	sb.WriteString("             File_dirname  text   ,\n")
	sb.WriteString("             File_basename text   ,\n")
	sb.WriteString("             nByte         integer,\n")
	sb.WriteString("             nBlank        integer,\n")
	sb.WriteString("             nComment      integer,\n")
	sb.WriteString("             nCode         integer,\n")
	sb.WriteString("             nComplexity   integer,\n")
