			}
		}
		sb.WriteString("# EOF\n")
		return sb.String()
	}
	for _, s := range summaries {
		lbl := fmt.Sprintf("{language=\"%s\"}", s.Name)
		sb.WriteString(fmt.Sprintf("scc_files%s %d\n", lbl, s.Count))
		sb.WriteString(fmt.Sprintf("scc_lines%s %d\n", lbl, s.Lines))
		sb.WriteString(fmt.Sprintf("scc_code%s %d\n", lbl, s.Code))
		sb.WriteString(fmt.Sprintf("scc_comments%s %d\n", lbl, s.Comment))
		sb.WriteString(fmt.Sprintf("scc_blanks%s %d\n", lbl, s.Blank))
		sb.WriteString(fmt.Sprintf("scc_complexity%s %d\n", lbl, s.Complexity))
		sb.WriteString(fmt.Sprintf("scc_bytes%s %d\n", lbl, s.Bytes))
	}
	return sb.String()
