		lo.set("reviewHours", lr.reviewHours)
		lo.set("preset", lr.preset)
		lo.set("averageComplexityMultiplier", lr.multiplier)
		lo.set("cycles", lr.cycles)
		out.set("locomo", lo)
	}
	out.set("totalFiles", tf)
	out.set("totalLines", tl)
	out.set("totalCode", tc)
	b, _ := json.MarshalIndent(out, "", "  ")
	return toolResult(string(b), false)
}

func runMCPServer() {
	reader := bufio.NewReader(os.Stdin)
	writer := bufio.NewWriter(os.Stdout)
	for {
		line, err := reader.ReadString('\n')
		if line == "" && err != nil {
			break
		}
		line = strings.TrimSpace(line)
		if line == "" {
			if err != nil {
				break
			}
			continue
		}
		var req rpcRequest
		if jerr := json.Unmarshal([]byte(line), &req); jerr != nil {
			writeRPC(writer, nil, nil, &rpcError{Code: -32700, Message: "Parse error"})
			if err != nil {
				break
			}
			continue
		}
		switch req.Method {
		case "initialize":
			writeRPC(writer, req.ID, map[string]interface{}{
				"protocolVersion": "2024-11-05",
				"capabilities":    map[string]interface{}{"tools": map[string]interface{}{}},
				"serverInfo":      map[string]interface{}{"name": "scc", "version": Version},
			}, nil)
		case "notifications/initialized", "notifications/cancelled":
			// no response for notifications
		case "ping":
			writeRPC(writer, req.ID, map[string]interface{}{}, nil)
		case "tools/list":
			writeRPC(writer, req.ID, toolsList(), nil)
		case "tools/call":
			var params struct {
				Name      string          `json:"name"`
				Arguments json.RawMessage `json:"arguments"`
			}
			json.Unmarshal(req.Params, &params)
			if params.Name != "analyze" {
				writeRPC(writer, req.ID, nil, &rpcError{Code: -32602, Message: fmt.Sprintf("tool '%s' not found: tool not found", params.Name)})
				break
			}
			var args analyzeArgs
			if len(params.Arguments) > 0 {
				json.Unmarshal(params.Arguments, &args)
			}
			writeRPC(writer, req.ID, runAnalyze(args), nil)
		default:
			if len(req.ID) == 0 {
				break
			}
			writeRPC(writer, req.ID, nil, &rpcError{Code: -32601, Message: fmt.Sprintf("Method %s not found", req.Method)})
		}
		if err != nil {
			break
		}
	}
	_ = sort.Strings
}
