	sb.WriteString("  lines_per_second: " + yamlFloat(float64(lines)/elapsed) + "\\n")
	if len(summaries) == 0 {
		sb.WriteString("{}\\n")
	} else {
		sorted := make([]*LanguageSummary, len(summaries))
		copy(sorted, summaries)
		sort.SliceStable(sorted, func(i, j int) bool { return yamlKeyLess(sorted[i].Name, sorted[j].Name) })
